DROP TABLE IF EXISTS `bookings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bookings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ref` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `guest_id` bigint unsigned NOT NULL,
  `transaction_id` bigint unsigned DEFAULT NULL,
  `full_names` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `extra_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `adult_no` int NOT NULL DEFAULT '1',
  `child_no` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `checked_in` datetime DEFAULT NULL,
  `checked_out` datetime DEFAULT NULL,
  `prices` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `reminded` bigint unsigned NOT NULL DEFAULT '0',
  `previous_change` tinyint(1) NOT NULL DEFAULT '0',
  `previous_cost` int NOT NULL DEFAULT '0',
  `previous_date` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `multi_room` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=299 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
